    "modal_doc4_desc": "Only transparent body black or blue ballpoint pen. Gel pens, fountain pens, or pencils strictly barred on OMR.",
    "modal_sec_barred": "🚫 2. Strictly Prohibited Items (Zero Tolerance)",
    "modal_sec_omr": "🎯 3. Five Golden Rules for Filling OMR Sheet",
    "modal_omr_r1_title": "Darken Circle Completely (● Correct vs ✕ Incorrect):",
    "modal_omr_r1_desc": "Do not leave circle incomplete or tick (✓). The optical scanner only reads fully blackened or blued circles.",
    "modal_omr_r2_title": "Carefully Bubble Roll No & Booklet Series First:",
    "modal_omr_r2_desc": "Before answering questions, bubble your Roll Number, Question Booklet Series (A, B, C, D) and Subject Code with zero errors.",
    "modal_omr_r3_title": "No Double Bubbling (Only One Option Per Question):",
    "modal_omr_r3_desc": "If multiple circles are darkened for a question, it is automatically rejected or incurs negative marks.",
    "modal_omr_r4_title": "Never Fold OMR & Strictly No Whitener / Eraser:",
    "modal_omr_r4_desc": "Scratching with blade or using liquid whitener is strictly prohibited. Avoid any stray marks on OMR timing tracks.",
    "modal_omr_r5_title": "Invigilator Signature & Thumb Impression Verification:",
    "modal_omr_r5_desc": "Ensure the invigilator has signed your OMR sheet and candidate attendance sheet has recorded your thumb impression before leaving.",
