    "faq_title": "Frequently Asked Questions (FAQ)",
    "faq_student_desk": "Student Help Desk",
    "faq_q1": "📸 How does the Photo & Signature Resizer work? Is my photo safe?",
    "faq_a1": "Your photo and signature are 100% safe. This tool processes images entirely inside your browser (Client-side HTML5 Canvas); no files are uploaded or stored on any server. It sizes images to 20-50 KB and exact dimensions required for SSC, UPSC, Railway, and State Police forms.",
    "faq_q2": "📑 What is the Official Notification Circular Decoder?",
    "faq_a2": "It analyzes complex 50-60 page official recruitment circulars into quick 1-minute summaries detailing application deadlines, vacancies, pay scales, age eligibility, exam patterns, and required documents.",
    "faq_q3": "📚 How do I access ₹10 Study Notes and Previous Year Questions (PYQs)?",
    "faq_a3": "Select your target exam and subject. Complete a quick ₹10 instant UPI payment via PhonePe, Google Pay, or Paytm QR code to download the high-yield PDF immediately.",
    "faq_q4": "🎂 How is category reservation age relaxation calculated in Age Calculator?",
    "faq_a4": "Calculations are performed strictly against the official cutoff date and your date of birth. Standard age relaxations (OBC 3 years, SC/ST 5 years, PwBD 10-15 years, Ex-Servicemen) are applied automatically.",
    "faq_q5": "🌐 Are all external links on the portal 100% official and safe?",
    "faq_a5": "Yes! All links are verified 24x7 directly from official government commission domains (.gov.in, .nic.in, .ac.in). We never direct users to fake links or third-party ads.",
