    "faq_student_desk": "மாணவர் உதவி மையம் (Student Help Desk)",
    "faq_q1": "📸 புகைப்படம் மற்றும் கையொப்ப அளவாக்கி எவ்வாறு செயல்படுகிறது? எனது படம் பாதுகாப்பானதா?",
    "faq_a1": "உங்கள் புகைப்படம் மற்றும் கையொப்பம் 100% பாதுகாப்பானது. இந்த கருவி உலாவியிலேயே (Client-side HTML5 Canvas) செயல்படுவதால் எந்த கோப்பும் சர்வரில் பதிவேற்றப்படாது. SSC, UPSC, ரயில்வே மற்றும் காவல்துறை விண்ணப்பங்களுக்கான 20-50 KB அளவுக்கு துல்லியமாக மாற்றித் தருகிறது.",
    "faq_q2": "📑 அதிகாரப்பூர்வ அறிவிப்பு சுற்றறிக்கை டிகோடர் என்றால் என்ன?",
    "faq_a2": "50-60 பக்கங்கள் கொண்ட அதிகாரப்பூர்வ அறிவிப்புகளிலிருந்து முக்கிய தேதிகள், காலியிடங்கள், ஊதியம், வயது வரம்பு, தேர்வு முறை மற்றும் ஆவணங்களை 1 நிமிட எளிய சுருக்கமாக வழங்குகிறது.",
    "faq_q3": "📚 ₹10 குறிப்புகள் மற்றும் முந்தைய ஆண்டு வினாத்தாள்களை (PYQ) பெறுவது எப்படி?",
    "faq_a3": "தேர்வைத் தேர்ந்தெடுத்து உங்கள் பாடக் குறிப்புகளைத் தேர்ந்தெடுக்கவும். PhonePe, Google Pay அல்லது Paytm மூலம் ₹10 UPI கட்டணம் செலுத்தி உடனடியாக உயர்தர PDF கோப்பைப் பதிவிறக்கலாம்.",
    "faq_q4": "🎂 வயது கணக்கீட்டில் (Age Calculator) இடஒதுக்கீட்டு தளர்வு எவ்வாறு கணக்கிடப்படுகிறது?",
    "faq_a4": "அதிகாரப்பூர்வ கட்-ஆஃப் தேதி மற்றும் பிறந்த தேதியை அடிப்படையாகக் கொண்டு துல்லியமாகக் கணக்கிடப்படுகிறது. OBC-க்கு 3 ஆண்டுகள், SC/ST-க்கு 5 ஆண்டுகள், மாற்றுத்திறனாளிகளுக்கு 10-15 ஆண்டுகள் தளர்வு தானாகவே கணக்கிடப்படுகிறது.",
    "faq_q5": "🌐 போர்ட்டலில் உள்ள அனைத்து இணைப்புகளும் 100% அதிகாரப்பூர்வமானவையா?",
    "faq_a5": "ஆம்! அனைத்து இணைப்புகளும் அதிகாரப்பூர்வ அரசு தளங்களுடன் (.gov.in, .nic.in, .ac.in) 24x7 தானாக சரிபார்க்கப்படுகின்றன. போலி அல்லது விளம்பர தள இணைப்புகள் வழங்கப்படுவதில்லை.",
