    "dopt_desc": "OBC-NCL, EWS, SC/ST சான்றிதழின் முக்கியமான தேதி செல்லுபடியை சரிபார்க்கவும், அங்கீகரிக்கப்பட்ட கையொப்பமிடும் அதிகாரிகளின் (DM/SDO/Tehsildar) சரிபார்ப்பைச் சரிபார்த்து, உங்கள் ஆட்சேர்ப்புத் தேர்வுக்கான தனிப்பயனாக்கப்பட்ட DV சரிபார்ப்புப் பட்டியலைத் தயாரிக்கவும்.",
