    "study_badge": "⏰ 50:10 பொமோடோரோ முறை மற்றும் அறிவாற்றல் உச்ச அட்டவணை",
    "study_desc": "உங்கள் தினசரி வழக்கப்படி (முழு நேர, வேலை அல்லது வார இறுதி மராத்தான்) அறிவியல் அட்டவணையை உருவாக்கவும். கணிதம், பகுத்தறிவு, ஜிஎஸ், மொழிகள் மற்றும் போலி சோதனைகளின் சமநிலையான இடங்களைத் தேர்வுசெய்து, உங்கள் தினசரி உற்பத்தித்திறன் 100% என்பதை உறுதிப்படுத்தவும்.",
