    "modal_hall_warning": "<strong>బయోమెట్రిక్ & గేట్ క్లోజింగ్ హెచ్చరిక:</strong> అడ్మిట్ కార్డ్‌లో పేర్కొన్న గేట్ మూసివేసే సమయానికి కనీసం 45 నిమిషాల ముందే పరీక్షా కేంద్రానికి చేరుకోండి.",
    "modal_sec_mandatory": "✅ 1. తప్పనిసరి పత్రాలు (ఈ 4 వస్తువులను తప్పక తీసుకెళ్లండి)",
