    "modal_doc2_desc": "ఆధార్ కార్డ్ / ఓటర్ ఐడి / పాన్ కార్డ్ / డ్రైవింగ్ లైసెన్స్. మొబైల్ ఫోటో అనుమతించబడదు.",
    "modal_doc3_title": "🖼️ 3. పాస్‌పోర్ట్ సైజు ఫోటోగ్రాఫ్‌లు (2 ఫోటోలు)",
    "modal_doc3_desc": "హాజరు పత్రంపై అతికించడానికి అడ్మిట్ కార్డ్‌లోని ఫోటోతో సరిపోలే కనీసం 2 ఫోటోలు.",
    "modal_doc4_title": "🖊️ 4. పారదర్శక బాల్‌పాయింట్ పెన్ (నలుపు / నీలం)",
    "modal_doc4_desc": "పారదర్శక నలుపు లేదా నీలం బాల్ పెన్ మాత్రమే. జెల్ పెన్నులు లేదా పెన్సిళ్లు ఖచ్చితంగా నిషిద్ధం.",
    "modal_sec_barred": "🚫 2. ఖచ్చితంగా నిషేధించబడిన వస్తువులు (జీరో టాలరెన్స్)",
