    "modal_omr_r1_title": "వృత్తాన్ని పూర్తిగా నల్లగా నింపండి:",
    "modal_omr_r1_desc": "వృత్తం బయటకు గీతలు గీయవద్దు లేదా టిక్ (✓) పెట్టవద్దు. పూర్తిగా నింపిన వృత్తాలనే స్కానర్ గుర్తిస్తుంది.",
    "modal_omr_r2_title": "రోల్ నంబర్ మరియు బుక్‌లెట్ కోడ్‌ను జాగ్రత్తగా పూరించండి:",
    "modal_omr_r2_desc": "ప్రశ్నలకు సమాధానాలు రాసే ముందు రోల్ నంబర్ మరియు బుక్‌లెట్ సిరీస్‌ను తప్పులు లేకుండా బబుల్ చేయండి.",
    "modal_omr_r3_title": "ఒక ప్రశ్నకు ఒకే వృత్తాన్ని నింపండి (డబుల్ బబ్లింగ్ వద్దు):",
    "modal_omr_r3_desc": "ఒక ప్రశ్నకు రెండు వృత్తాలు నింపితే ఆ సమాధానం రద్దవుతుంది మరియు నెగెటివ్ మార్కులు పడతాయి.",
