    "faq_title": "తరచుగా అడిగే ప్రశ్నలు (FAQ)",
    "faq_student_desk": "విద్యార్థి సహాయ కేంద్రం (Student Help Desk)",
    "faq_q1": "📸 ఫోటో & సంతకం రీసైజర్ ఎలా పనిచేస్తుంది? నా ఫోటో సురక్షితమేనా?",
    "faq_a1": "మీ ఫోటో మరియు సంతకం 100% సురక్షితం. ఈ సాధనం మీ బ్రౌజర్‌లో మాత్రమే (క్లయింట్-సైడ్ HTML5 కాన్వాస్) ప్రాసెస్ చేయబడుతుంది, సర్వర్‌లో అప్‌లోడ్ చేయబడదు. SSC, UPSC, రైల్వే మరియు పోలీస్ రిక్రూట్‌మెంట్‌ల కొరకు 20-50 KB పరిమాణంలోకి మారుస్తుంది.",
    "faq_q2": "📑 అధికారిక నోటిఫికేషన్ సర్క్యులర్ డీకోడర్ అంటే ఏమిటి?",
    "faq_a2": "50-60 పేజీల రిక్రూట్‌మెంట్ నోటిఫికేషన్‌లను 1 నిమిషంలో సులభమైన భాషలో ముఖ్యమైన తేదీలు, ఖాళీలు, జీతం, వయోపరిమితి మరియు పరీక్షా విధానం వివరాలతో అందిస్తుంది.",
    "faq_q3": "📚 ₹10 స్టడీ నోట్స్ మరియు పాత ప్రశ్నపత్రాలు (PYQ) ఎలా పొందాలి?",
    "faq_a3": "పరీక్షను ఎంచుకుని మీ సబ్జెక్ట్ నోట్స్ ఎంచుకోండి. PhonePe, Google Pay లేదా Paytm ద్వారా ₹10 UPI చెల్లించి వెంటనే హై-క్వాలిటీ PDF డౌన్‌లోడ్ చేసుకోండి.",
    "faq_q4": "🎂 ఏజ్ కాలిక్యులేటర్‌లో రిజర్వేషన్ సడలింపు ఎలా లెక్కిస్తారు?",
    "faq_a4": "అధికారిక కటాఫ్ తేదీ మరియు పుట్టిన తేదీ ఆధారంగా OBCకి 3 సంవత్సరాలు, SC/STకి 5 సంవత్సరాలు, PwBDకి 10-15 సంవత్సరాల సడలింపు స్వయంచಾಲకంగా వర్తిస్తుంది.",
    "faq_q5": "🌐 పోర్టల్‌లోని లింక్‌లన్నీ 100% అధికారికమైనవేనా?",
    "faq_a5": "అవును! అన్ని లింక్‌లు అధికారిక ప్రభుత్వ వెబ్‌సైట్‌ల (.gov.in, .nic.in) ద్వారా 24x7 స్వయంచಾಲకంగా ధృవీకరించబడతాయి.",
