    "faq_q1": "📸 फोटो आणि स्वाक्षरी रिसाइझर कसे काम करते? माझा फोटो सुरक्षित आहे का?",
    "faq_a1": "तुमचा फोटो आणि स्वाक्षरी १००% सुरक्षित आहे. हे टूल पूर्णपणे ब्राउझरमध्ये (Client-side HTML5 Canvas) कार्य करते, सर्व्हरवर अपलोड होत नाही. SSC, UPSC, रेल्वे आणि पोलीस भरतीसाठी २०-५० KB मध्ये त्वरित रूपांतरित करते.",
    "faq_q2": "📑 अधिकृत अधिसूचना परिपत्रक डिकोडर काय आहे?",
    "faq_a2": "५०-६० पानांच्या भरती अधिसूचनेतील अंतिम मुदत, पदसंख्या, वेतन, वयोमर्यादा व परीक्षा पद्धती १ मिनिटात सोप्या भाषेत स्पष्ट करते.",
    "faq_q3": "📚 ₹१० अभ्यास नोट्स आणि जुने प्रश्न (PYQ) कसे मिळवावेत?",
    "faq_a3": "परीक्षेची निवड करून PhonePe, Google Pay किंवा Paytm द्वारे फक्त ₹१० चे UPI पेमेंट करा आणि तात्काळ उच्च दर्जाची PDF डाउनलोड करा.",
    "faq_q4": "🎂 वय गणनेमध्ये (Age Calculator) आरक्षणाची सवलत कशी मोजली जाते?",
    "faq_a4": "अधिकृत कटऑफ तारीख आणि जन्मतारखेनुसार OBC ३ वर्षे, SC/ST ५ वर्षे आणि PwBD १०-१५ वर्षे वयोमर्यादा सवलत आपोआप लागू होते.",
