    "modal_sec_mandatory": "✅ ১. বাধ্যতামূলক নথিপত্র (এই ৪টি জিনিস সাথে নেওয়া আবশ্যক)",
    "modal_doc1_title": "📄 ১. মূল অ্যাডমিট কার্ড (স্পষ্ট প্রিন্টআউট)",
    "modal_doc1_desc": "পরিষ্কার প্রিন্টআউট (রঙ বা পরিষ্কার কালো এবং সাদা)। বারকোড এবং রোল নম্বরে কোনও বলি থাকা উচিত নয়। পরীক্ষকের সামনে সাইন ইন করুন।",
