    "modal_doc3_desc": "উপস্থিতি পত্রের জন্য প্রবেশপত্রে আপলোড করা ছবির অনুরূপ ন্যূনতম 2টি পাসপোর্ট আকারের রঙিন ছবি বহন করুন।",
    "modal_doc4_title": "🖊️ ৪. স্বচ্ছ বলপয়েন্ট কলম (কালো / নীল)",
    "modal_doc4_desc": "স্বচ্ছ শরীর কালো বা নীল বল কলম শুধুমাত্র. জেল কলম, ফাউন্টেন পেন বা পেন্সিল ওএমআরে কঠোরভাবে নিষিদ্ধ।",
