    "modal_omr_r1_title": "বৃত্তটি সম্পূর্ণভাবে ভরাট করুন:",
    "modal_omr_r1_desc": "কলমটি সরিয়ে ফেলবেন না বা বৃত্তের বাইরে অসম্পূর্ণ বা টিক (✓) রাখবেন না। স্ক্যানার শুধুমাত্র সম্পূর্ণরূপে ভরা কালো/নীল চেনাশোনা পড়ে।",
    "modal_omr_r2_title": "রোল নম্বর ও বুকলেট কোড সতর্কতার সাথে পূরণ করুন:",
    "modal_omr_r2_desc": "প্রশ্ন করার চেষ্টা করার আগে, রোল নম্বর, প্রশ্ন পুস্তিকা সিরিজ (A, B, C, D) এবং বিষয় কোড খুব সাবধানে পূরণ করুন।",
    "modal_omr_r3_title": "একটি প্রশ্নের জন্য কেবল একটি বৃত্তই ভরাট করুন:",
    "modal_omr_r3_desc": "যদি একটি প্রশ্নের দুটি বৃত্ত ভরা হয়, তবে সেই উত্তরটি স্বয়ংক্রিয়ভাবে বাতিল হয়ে যায় এবং নেতিবাচক মার্কিং সহ কাগজে নম্বর কাটা হয়।",
    "modal_omr_r4_title": "ওএমআর শিট ভাঁজ করবেন না ও হোয়াইটনার ব্যবহার করবেন না:",
    "modal_omr_r4_desc": "ব্লেড স্ক্র্যাচ করা, ইরেজার বা হোয়াইটনার/ফ্লুইড ব্যবহার করা কঠোরভাবে নিষিদ্ধ। OMR শীটের বারকোড বা টাইমিং ট্র্যাকে কোনো অতিরিক্ত চিহ্ন তৈরি করবেন না।",
    "modal_omr_r5_title": "পরিদর্শকের স্বাক্ষর এবং বুড়ো আঙুলের ছাপ যাচাইকরণ:",
