    "qual_grad": "স্নাতক",
    "qual_iti": "আইটিআই / ডিপ্লোমা",
    "faq_title": "প্রায়শই জিজ্ঞাসিত প্রশ্নাবলী (FAQ)",
    "faq_student_desk": "ছাত্র সহায়তা কেন্দ্র (Student Help Desk)",
    "faq_q1": "📸 ছবি ও স্বাক্ষর রিসাইজার কীভাবে কাজ করে? আমার ছবি কি নিরাপদ?",
    "faq_a1": "আপনার ছবি এবং স্বাক্ষর 100% সুরক্ষিত। এই টুল ব্রাউজারের ভিতরে চলে (ক্লায়েন্ট-সাইড HTML5 ক্যানভাসে) এবং কোনো সার্ভারে আপলোড বা সংরক্ষণ করা হয় না। এটি অবিলম্বে SSC, UPSC, রেলওয়ে এবং রাজ্য পুলিশের অফিসিয়াল 20-50 KB এবং পিক্সেল প্রয়োজনীয়তা পূরণ করে।",
    "faq_q2": "📑 অফিসিয়াল বিজ্ঞপ্তি সার্কুলার ডিকোডার কী?",
    "faq_a2": "সরকারি নিয়োগ বিজ্ঞপ্তির 50-60 পৃষ্ঠার মধ্যে, আবেদনের শেষ তারিখ, মোট পদ, বেতন স্কেল, বয়স সীমা, পরীক্ষার প্যাটার্ন এবং প্রয়োজনীয় নথিগুলির মতো গুরুত্বপূর্ণ বিষয়গুলি 1 মিনিটে সহজ ভাষায় উপস্থাপন করা হয়েছে।",
    "faq_q3": "📚 ₹১০ স্টাডি নোটস এবং পূর্ববর্তী বছরের প্রশ্ন (PYQ) কীভাবে পাবেন?",
    "faq_a3": "পরীক্ষা নির্বাচন করে আপনার পছন্দের বিষয়ের নোট বাছাই করুন। PhonePe, Google Pay বা Paytm-এর মাধ্যমে মাত্র ₹10-এর সরাসরি UPI QR পেমেন্ট করলে তাত্ক্ষণিক উচ্চ-মানের PDF ডাউনলোড আনলক হয়।",
    "faq_q4": "🎂 বয়স গণনায় (Age Calculator) সংরক্ষণের ছাড় কীভাবে গণনা করা হয়?",
    "faq_a4": "কমিশন কাটঅফ তারিখ এবং জন্ম তারিখের ভিত্তিতে সঠিক গণনা করা হয়। এতে, OBC-এর জন্য 3 বছর, SC/ST-এর জন্য 5 বছর, PwBD-এর জন্য 10-15 বছর এবং প্রাক্তন সেনাদের জন্য নিয়ম অনুযায়ী স্বয়ংক্রিয়ভাবে শিথিলতা প্রযোজ্য হয়।",
    "faq_q5": "🌐 পোর্টালের সমস্ত লিঙ্ক কি ১০০% অফিসিয়াল?",
    "faq_a5": "হ্যাঁ! আমাদের সিস্টেম 24x7 স্বায়ত্তশাসিতভাবে অফিসিয়াল কমিশনের সার্ভারগুলি যাচাই করে (.gov.in, .nic.in, .ac.in)। জাল বা বিভ্রান্তিকর বিজ্ঞাপন ধারণকারী কোনো ওয়েবসাইটের লিঙ্ক প্রদান করা হয় না.",
