    "faq_title": "ಪದೇ ಪದೇ ಕೇಳಲಾಗುವ ಪ್ರಶ್ನೆಗಳು (FAQ)",
    "faq_student_desk": "ವಿದ್ಯಾರ್ಥಿ ಸಹಾಯ ಕೇಂದ್ರ (Student Help Desk)",
    "faq_q1": "📸 ಫೋಟೋ ಮತ್ತು ಸಹಿ ಮರುಗಾತ್ರಗೊಳಿಸುವಿಕೆ ಹೇಗೆ ಕಾರ್ಯನಿರ್ವಹಿಸುತ್ತದೆ? ನನ್ನ ಫೋಟೋ ಸುರಕ್ಷಿತವೇ?",
    "faq_a1": "ನಿಮ್ಮ ಫೋಟೋ ಮತ್ತು ಸಹಿ 100% ಸುರಕ್ಷಿತವಾಗಿದೆ. ಈ ಉಪಕರಣವು ಬ್ರೌಸರ್‌ನಲ್ಲಿಯೇ (Client-side HTML5 Canvas) ಕಾರ್ಯನಿರ್ವಹಿಸುತ್ತದೆ. SSC, UPSC, ರೈಲ್ವೆ ಮತ್ತು ಪೊಲೀಸ್ ಅರ್ಜಿಗಳಿಗೆ 20-50 KB ಗೆ ನಿಖರವಾಗಿ ಬದಲಾಯಿಸುತ್ತದೆ.",
    "faq_q2": "📑 ಅಧಿಕೃತ ಅಧಿಸೂಚನೆ ಸುತ್ತೋಲೆ ಡಿಕೋಡರ್ ಎಂದರೇನು?",
    "faq_a2": "50-60 ಪುಟಗಳ ನೇಮಕಾತಿ ಅಧಿಸೂಚನೆಯ ಕೊನೆಯ ದಿನಾಂಕ, ಹುದ್ದೆಗಳು, ವೇತನ, ವಯೋಮಿತಿ ಮತ್ತು ಪರೀಕ್ಷಾ ವಿವರಗಳನ್ನು 1 ನಿಮಿಷದಲ್ಲಿ ಸರಳವಾಗಿ ನೀಡುತ್ತದೆ.",
    "faq_q3": "📚 ₹10 ನೋಟ್ಸ್ ಮತ್ತು ಹಿಂದಿನ ವರ್ಷದ ಪ್ರಶ್ನೆಪತ್ರಿಕೆಗಳನ್ನು (PYQ) ಪಡೆಯುವುದು ಹೇಗೆ?",
    "faq_a3": "ಪರೀಕ್ಷೆಯನ್ನು ಆರಿಸಿ PhonePe, Google Pay ಅಥವಾ Paytm ಮೂಲಕ ₹10 UPI ಪಾವತಿ ಮಾಡಿ ತಕ್ಷಣ ಉತ್ತಮ ಗುಣಮಟ್ಟದ PDF ಡೌನ್‌ಲೋಡ್ ಮಾಡಿ.",
    "faq_q4": "🎂 ವಯಸ್ಸಿನ ಕ್ಯಾಲ್ಕುಲೇಟರ್‌ನಲ್ಲಿ ಮೀಸಲಾತಿ ವಯೋಮಿತಿ ಸಡಿಲಿಕೆ ಹೇಗೆ ಲೆಕ್ಕಹಾಕಲಾಗುತ್ತದೆ?",
    "faq_a4": "ಅಧಿಕೃತ ಕಟ್‌ಆಫ್ ದಿನಾಂಕ ಮತ್ತು ಜನ್ಮ ದಿನಾಂಕದ ಆಧಾರದ ಮೇಲೆ OBC 3 ವರ್ಷ, SC/ST 5 ವರ್ಷ, PwBD 10-15 ವರ್ಷಗಳ ಸಡಿಲಿಕೆಯನ್ನು ಸ್ವಯಂಚಾಲಿತವಾಗಿ ಅನ್ವಯಿಸಲಾಗುತ್ತದೆ.",
    "faq_q5": "🌐 ಪೋರ್ಟಲ್‌ನಲ್ಲಿರುವ ಎಲ್ಲಾ ಲಿಂಕ್‌ಗಳು 100% ಅಧಿಕೃತವೇ?",
