    "faq_a1": "നിങ്ങളുടെ ഫോട്ടോയും ഒപ്പും 100% സുരക്ഷിതമാണ്. ഈ ടൂൾ ബ്രൗസറിൽ തന്നെ പ്രവർത്തിക്കുന്നു (Client-side HTML5 Canvas). SSC, UPSC, റെയിൽവേ, പോലീസ് ഫോമുകൾക്കായി 20-50 KB കൃത്യമായ വലുപ്പത്തിലേക്ക് മാറ്റുന്നു.",
