    "faq_a2": "50-60 പേജുകളുള്ള വിജ്ഞാപനങ്ങളിൽ നിന്ന് അവസാന തീയതി, ഒഴിവുകൾ, ശമ്പളം, പ്രായപരിധി എന്നിവ 1 മിനിറ്റിൽ ലളിതമായി വിശദീകരിക്കുന്നു.",
    "faq_q3": "📚 ₹10 പഠന കുറിപ്പുകളും പഴയ ചോദ്യപേപ്പറുകളും (PYQ) എങ്ങനെ ലഭിക്കും?",
    "faq_a3": "പരീക്ഷ തിരഞ്ഞെടുത്ത് PhonePe, Google Pay അല്ലെങ്കിൽ Paytm വഴി ₹10 UPI പേയ്‌മെന്റ് നടത്തി ഉടൻ തന്നെ ഉയർന്ന നിലവാരമുള്ള PDF ഡൗൺലോഡ് ചെയ്യാം.",
    "faq_q4": "🎂 പ്രായപരിധി കാൽക്കുലേറ്ററിൽ സംവരണ ഇളവ് എങ്ങനെ കണക്കാക്കുന്നു?",
    "faq_a4": "കട്ട്ഓഫ് തീയതിയും ജനനത്തീയതിയും അടിസ്ഥാനമാക്കി OBC 3 വർഷം, SC/ST 5 വർഷം, ഭിന്നശേഷിക്കാർക്ക് 10-15 വർഷം ഇളവ് സ്വയമേവ കണക്കാക്കുന്നു.",
