    "anskey_notice": "<strong>ਮਹੱਤਵਪੂਰਨ ਜਾਣਕਾਰੀ:</strong> ਇਤਰਾਜ਼ ਦਰਜ ਕਰਨ ਲਈ, ਸਬੰਧਤ ਕਮਿਸ਼ਨ ਦੀ ਅਧਿਕਾਰਤ ਵੈੱਬਸਾਈਟ 'ਤੇ ਲੌਗਇਨ ਆਈਡੀ ਅਤੇ ਜਨਮ ਮਿਤੀ ਦਰਜ ਕਰੋ। ਚਾਰਜਬੈਕ ਸਿਰਫ਼ ਵੈਧ ਇਤਰਾਜ਼ਾਂ 'ਤੇ ਹੀ ਲਾਗੂ ਹੁੰਦਾ ਹੈ।",
    "modal_hall_tag": "ਅਧਿਕਾਰਤ ਪ੍ਰੀਖਿਆ ਹਾਲ ਨਿਯਮ • OMR ਸੁਨਹਿਰੀ ਨਿਯਮ",
    "modal_hall_title": "ਪ੍ਰੀਖਿਆ ਦਿਵਸ ਹਾਲ ਮਾਸਟਰ ਚੈੱਕਲਿਸਟ ਅਤੇ OMR ਨਿਯਮ",
    "modal_hall_warning": "<strong>ਬਾਇਓਮੈਟ੍ਰਿਕ ਅਤੇ ਗੇਟ ਬੰਦ ਹੋਣ ਦੀ ਚੇਤਾਵਨੀ:</strong> ਦਾਖਲਾ ਕਾਰਡ 'ਤੇ ਦਰਸਾਏ ਗੇਟ ਬੰਦ ਹੋਣ ਦੇ ਸਮੇਂ ਤੋਂ ਘੱਟੋ-ਘੱਟ 45 ਮਿੰਟ ਪਹਿਲਾਂ ਪ੍ਰੀਖਿਆ ਕੇਂਦਰ 'ਤੇ ਪਹੁੰਚੋ। ਜੇਕਰ ਗੇਟ ਬੰਦ ਹੋਣ ਤੋਂ ਬਾਅਦ 1 ਸਕਿੰਟ ਦੀ ਵੀ ਦੇਰੀ ਹੁੰਦੀ ਹੈ ਤਾਂ ਐਂਟਰੀ ਨਹੀਂ ਦਿੱਤੀ ਜਾਵੇਗੀ।",
    "modal_sec_mandatory": "✅ 1. ਲਾਜ਼ਮੀ ਦਸਤਾਵੇਜ਼ (ਇਹ 4 ਚੀਜ਼ਾਂ ਜ਼ਰੂਰ ਨਾਲ ਲੈ ਕੇ ਜਾਓ)",
    "modal_doc1_title": "📄 1. ਅਸਲ ਐਡਮਿਟ ਕਾਰਡ (ਸਾਫ਼ ਪ੍ਰਿੰਟਆਊਟ)",
    "modal_doc1_desc": "ਸਾਫ਼ ਪ੍ਰਿੰਟਆਊਟ (ਰੰਗ ਜਾਂ ਸਾਫ਼ ਕਾਲਾ ਅਤੇ ਚਿੱਟਾ)। ਬਾਰਕੋਡ ਅਤੇ ਰੋਲ ਨੰਬਰ 'ਤੇ ਕੋਈ ਝੁਰੜੀਆਂ ਨਹੀਂ ਹੋਣੀਆਂ ਚਾਹੀਦੀਆਂ। ਇਮਤਿਹਾਨ ਦੇਣ ਵਾਲੇ ਦੇ ਸਾਹਮਣੇ ਸਾਈਨ ਕਰੋ.",
    "modal_doc2_title": "🪪 2. ਅਸਲ ਫੋਟੋ ਸ਼ਨਾਖਤੀ ਕਾਰਡ (ਪੂਰੀ ਜਨਮ ਮਿਤੀ ਸਮੇਤ)",
    "modal_doc2_desc": "ਆਧਾਰ ਕਾਰਡ (ਪੂਰੀ ਜਨਮ ਮਿਤੀ DD/MM/YYYY ਦੇ ਨਾਲ) / ਪੈਨ ਕਾਰਡ / ਵੋਟਰ ਕਾਰਡ / ਡਰਾਈਵਿੰਗ ਲਾਇਸੈਂਸ / ਪਾਸਪੋਰਟ। (ਮੋਬਾਈਲ ਫੋਟੋ ਅਵੈਧ)।",
    "modal_doc3_title": "🖼️ 3. ਪਾਸਪੋਰਟ ਸਾਈਜ਼ ਫੋਟੋਆਂ (2 ਫੋਟੋਆਂ)",
    "modal_doc3_desc": "ਹਾਜ਼ਰੀ ਸ਼ੀਟ ਲਈ ਦਾਖਲਾ ਕਾਰਡ 'ਤੇ ਅਪਲੋਡ ਕੀਤੀ ਗਈ ਫੋਟੋ ਦੇ ਸਮਾਨ ਘੱਟੋ-ਘੱਟ 2 ਪਾਸਪੋਰਟ ਆਕਾਰ ਦੀਆਂ ਰੰਗੀਨ ਫੋਟੋਆਂ ਨਾਲ ਰੱਖੋ।",
    "modal_doc4_title": "🖊️ 4. ਪਾਰਦਰਸ਼ੀ ਬਾਲਪੁਆਇੰਟ ਪੈੱਨ (ਕਾਲਾ / ਨੀਲਾ)",
    "modal_doc4_desc": "ਪਾਰਦਰਸ਼ੀ ਸਰੀਰ ਕਾਲਾ ਜਾਂ ਨੀਲਾ ਬਾਲ ਪੈੱਨ ਹੀ। ਜੈੱਲ ਪੈੱਨ, ਫਾਊਂਟੇਨ ਪੈੱਨ ਜਾਂ ਪੈਨਸਿਲ ਦੀ OMR 'ਤੇ ਸਖ਼ਤ ਮਨਾਹੀ ਹੈ।",
    "modal_sec_barred": "🚫 2. ਪੂਰੀ ਤਰ੍ਹਾਂ ਮਨਾਹੀ ਵਾਲੀਆਂ ਵਸਤੂਆਂ (ਸਖ਼ਤ ਮਨਾਹੀ)",
    "modal_sec_omr": "🎯 3. OMR ਸ਼ੀਟ ਭਰਨ ਦੇ 5 ਸੁਨਹਿਰੀ ਨਿਯਮ",
    "modal_omr_r1_title": "ਚੱਕਰ ਨੂੰ ਪੂਰੀ ਤਰ੍ਹਾਂ ਕਾਲਾ ਭਰੋ:",
    "modal_omr_r1_desc": "ਪੈੱਨ ਨੂੰ ਨਾ ਹਟਾਓ ਜਾਂ ਅਧੂਰਾ ਨਾ ਲਗਾਓ ਜਾਂ ਚੱਕਰ ਦੇ ਬਾਹਰ ਟਿੱਕ (✓) ਨਾ ਕਰੋ। ਸਕੈਨਰ ਸਿਰਫ਼ ਪੂਰੀ ਤਰ੍ਹਾਂ ਭਰੇ ਕਾਲੇ/ਨੀਲੇ ਚੱਕਰਾਂ ਨੂੰ ਪੜ੍ਹਦਾ ਹੈ।",
    "modal_omr_r2_title": "ਰੋਲ ਨੰਬਰ ਅਤੇ ਬੁੱਕਲੈੱਟ ਕੋਡ ਧਿਆਨ ਨਾਲ ਭਰੋ:",
    "modal_omr_r2_desc": "ਪ੍ਰਸ਼ਨ ਕਰਨ ਦੀ ਕੋਸ਼ਿਸ਼ ਕਰਨ ਤੋਂ ਪਹਿਲਾਂ, ਰੋਲ ਨੰਬਰ, ਪ੍ਰਸ਼ਨ ਪੁਸਤਿਕਾ ਲੜੀ (ਏ, ਬੀ, ਸੀ, ਡੀ) ਅਤੇ ਵਿਸ਼ਾ ਕੋਡ ਨੂੰ ਬਹੁਤ ਧਿਆਨ ਨਾਲ ਭਰੋ।",
    "modal_omr_r3_title": "ਇੱਕ ਪ੍ਰਸ਼ਨ ਲਈ ਸਿਰਫ਼ ਇੱਕ ਚੱਕਰ ਭਰੋ (ਡਬਲ ਬਬਲਿੰਗ ਨਾ ਕਰੋ):",
    "modal_omr_r3_desc": "ਜੇਕਰ ਕਿਸੇ ਸਵਾਲ ਦੇ ਦੋ ਚੱਕਰ ਭਰੇ ਜਾਂਦੇ ਹਨ, ਤਾਂ ਉਹ ਜਵਾਬ ਆਪਣੇ ਆਪ ਰੱਦ ਹੋ ਜਾਂਦਾ ਹੈ ਅਤੇ ਨੈਗੇਟਿਵ ਮਾਰਕਿੰਗ ਨਾਲ ਪੇਪਰ ਵਿੱਚ ਅੰਕ ਕੱਟੇ ਜਾਂਦੇ ਹਨ।",
    "modal_omr_r4_title": "OMR ਸ਼ੀਟ ਨੂੰ ਕਦੇ ਨਾ ਮੋੜੋ ਅਤੇ ਵ੍ਹਾਈਟਨਰ ਦੀ ਵਰਤੋਂ ਨਾ ਕਰੋ:",
    "modal_omr_r4_desc": "ਬਲੇਡ ਨੂੰ ਖੁਰਚਣ, ਇਰੇਜ਼ਰ ਜਾਂ ਵਾਈਟਨਰ/ਤਰਲ ਦੀ ਵਰਤੋਂ ਕਰਨ ਦੀ ਸਖ਼ਤ ਮਨਾਹੀ ਹੈ। OMR ਸ਼ੀਟ ਦੇ ਬਾਰਕੋਡ ਜਾਂ ਟਾਈਮਿੰਗ ਟਰੈਕ 'ਤੇ ਕੋਈ ਵਾਧੂ ਨਿਸ਼ਾਨ ਨਾ ਬਣਾਓ।",
    "modal_omr_r5_title": "ਨਿਗਰਾਨ ਦੇ ਦਸਤਖਤ ਅਤੇ ਅੰਗੂਠੇ ਦਾ ਨਿਸ਼ਾਨ ਯਕੀਨੀ ਬਣਾਓ:",
    "modal_omr_r5_desc": "ਇਮਤਿਹਾਨ ਖਤਮ ਹੋਣ ਤੋਂ ਪਹਿਲਾਂ, ਇਹ ਯਕੀਨੀ ਬਣਾਓ ਕਿ ਇਮਤਿਹਾਨ ਦੇਣ ਵਾਲੇ ਨੇ ਤੁਹਾਡੇ OMR 'ਤੇ ਦਸਤਖਤ ਕੀਤੇ ਹਨ ਅਤੇ ਹਾਜ਼ਰੀ ਨੂੰ ਚਿੰਨ੍ਹਿਤ ਕੀਤਾ ਗਿਆ ਹੈ।",
