    "qual_12th": "12ਵੀਂ ਪਾਸ",
    "qual_grad": "ਗ੍ਰੈਜੂਏਟ",
    "qual_iti": "ਆਈਟੀਆਈ / ਡਿਪਲੋਮਾ",
    "faq_title": "ਅਕਸਰ ਪੁੱਛੇ ਜਾਣ ਵਾਲੇ ਸਵਾਲ (FAQ)",
    "faq_student_desk": "ਵਿਦਿਆਰਥੀ ਸਹਾਇਤਾ ਕੇਂਦਰ (Student Help Desk)",
    "faq_q1": "📸 ਫੋਟੋ ਅਤੇ ਦਸਤਖਤ ਰੀਸਾਈਜ਼ਰ ਕਿਵੇਂ ਕੰਮ ਕਰਦਾ ਹੈ? ਕੀ ਮੇਰੀ ਫੋਟੋ ਸੁਰੱਖਿਅਤ ਹੈ?",
    "faq_a1": "ਤੁਹਾਡੀ ਫੋਟੋ ਅਤੇ ਦਸਤਖਤ 100% ਸੁਰੱਖਿਅਤ ਹਨ। ਇਹ ਟੂਲ ਬ੍ਰਾਊਜ਼ਰ ਦੇ ਅੰਦਰ ਚੱਲਦਾ ਹੈ (ਕਲਾਇੰਟ-ਸਾਈਡ HTML5 ਕੈਨਵਸ 'ਤੇ) ਅਤੇ ਕਿਸੇ ਵੀ ਸਰਵਰ 'ਤੇ ਅੱਪਲੋਡ ਜਾਂ ਸਟੋਰ ਨਹੀਂ ਕੀਤਾ ਜਾਂਦਾ ਹੈ। ਇਹ SSC, UPSC, ਰੇਲਵੇ ਅਤੇ ਰਾਜ ਪੁਲਿਸ ਦੀਆਂ ਅਧਿਕਾਰਤ 20-50 KB ਅਤੇ ਪਿਕਸਲ ਲੋੜਾਂ ਨੂੰ ਤੁਰੰਤ ਪੂਰਾ ਕਰਦਾ ਹੈ।",
    "faq_q2": "📑 ਅਧਿਕਾਰਤ ਨੋਟੀਫਿਕੇਸ਼ਨ ਸਰਕੂਲਰ ਡੀਕੋਡਰ ਕੀ ਹੈ?",
    "faq_a2": "ਸਰਕਾਰੀ ਭਰਤੀ ਨੋਟੀਫਿਕੇਸ਼ਨ ਦੇ 50-60 ਪੰਨਿਆਂ ਵਿੱਚੋਂ, ਮਹੱਤਵਪੂਰਨ ਚੀਜ਼ਾਂ ਜਿਵੇਂ ਕਿ ਅਰਜ਼ੀ ਦੀ ਆਖਰੀ ਮਿਤੀ, ਕੁੱਲ ਅਸਾਮੀਆਂ, ਤਨਖਾਹ ਸਕੇਲ, ਉਮਰ ਸੀਮਾ, ਪ੍ਰੀਖਿਆ ਪੈਟਰਨ ਅਤੇ ਲੋੜੀਂਦੇ ਦਸਤਾਵੇਜ਼ 1 ਮਿੰਟ ਵਿੱਚ ਆਸਾਨ ਭਾਸ਼ਾ ਵਿੱਚ ਪੇਸ਼ ਕੀਤੇ ਗਏ ਹਨ।",
    "faq_q3": "📚 ₹10 ਸਟੱਡੀ ਨੋਟਸ ਅਤੇ ਪਿਛਲੇ ਸਾਲਾਂ ਦੇ ਪ੍ਰਸ਼ਨ (PYQ) ਕਿਵੇਂ ਪ੍ਰਾਪਤ ਕਰੀਏ?",
    "faq_a3": "ਇਮਤਿਹਾਨ ਦੀ ਚੋਣ ਕਰਕੇ ਆਪਣੇ ਮਨਪਸੰਦ ਵਿਸ਼ੇ ਦੇ ਨੋਟਸ ਦੀ ਚੋਣ ਕਰੋ। PhonePe, Google Pay ਜਾਂ Paytm ਰਾਹੀਂ ਸਿਰਫ਼ ₹10 ਦਾ ਸਿੱਧਾ UPI QR ਭੁਗਤਾਨ ਕਰਨ ਨਾਲ ਤੁਰੰਤ ਉੱਚ-ਗੁਣਵੱਤਾ ਵਾਲੇ PDF ਡਾਊਨਲੋਡ ਨੂੰ ਅਨਲੌਕ ਕੀਤਾ ਜਾਂਦਾ ਹੈ।",
    "faq_q4": "🎂 ਉਮਰ ਕੈਲਕੁਲੇਟਰ ਵਿੱਚ ਰਾਖਵਾਂਕਰਨ ਛੋਟ ਕਿਵੇਂ ਗਿਣੀ ਜਾਂਦੀ ਹੈ?",
    "faq_a4": "ਸਹੀ ਗਣਨਾ ਕਮਿਸ਼ਨ ਕੱਟਆਫ ਮਿਤੀ ਅਤੇ ਜਨਮ ਮਿਤੀ ਦੇ ਆਧਾਰ 'ਤੇ ਕੀਤੀ ਜਾਂਦੀ ਹੈ। ਇਸ ਵਿੱਚ, OBC ਲਈ 3 ਸਾਲ, SC/ST ਲਈ 5 ਸਾਲ, PwBD ਲਈ 10-15 ਸਾਲ ਅਤੇ ਸਾਬਕਾ ਸੈਨਿਕਾਂ ਲਈ ਨਿਯਮਾਂ ਅਨੁਸਾਰ ਛੋਟ ਆਪਣੇ ਆਪ ਲਾਗੂ ਹੁੰਦੀ ਹੈ।",
    "faq_q5": "🌐 ਕੀ ਪੋਰਟਲ 'ਤੇ ਦਿੱਤੇ ਸਾਰੇ ਲਿੰਕ 100% ਅਧਿਕਾਰਤ ਹਨ?",
    "faq_a5": "ਹਾਂ! ਸਾਡਾ ਸਿਸਟਮ 24x7 ਖੁਦਮੁਖਤਿਆਰ ਤੌਰ 'ਤੇ ਅਧਿਕਾਰਤ ਕਮਿਸ਼ਨਾਂ (.gov.in, .nic.in, .ac.in) ਦੇ ਸਰਵਰਾਂ ਦੀ ਪੁਸ਼ਟੀ ਕਰਦਾ ਹੈ। ਜਾਅਲੀ ਜਾਂ ਗੁੰਮਰਾਹਕੁੰਨ ਇਸ਼ਤਿਹਾਰਾਂ ਵਾਲੀ ਕਿਸੇ ਵੀ ਵੈਬਸਾਈਟ ਦੇ ਲਿੰਕ ਪ੍ਰਦਾਨ ਨਹੀਂ ਕੀਤੇ ਗਏ ਹਨ।",
    "report_broken_btn": "ਸਮੱਸਿਆ / ਖਰਾਬ ਲਿੰਕ ਰਿਪੋਰਟ ਕਰੋ",
