    "anskey_mock_btn": "📝 ମାଗଣା ମକ୍ ଟେଷ୍ଟ",
    "anskey_notice": "<strong> ଗୁରୁତ୍ୱପୂର୍ଣ୍ଣ ସୂଚନା: </ strong> ଏକ ଆପତ୍ତି ଉପସ୍ଥାପନ କରିବାକୁ, ସଂପୃକ୍ତ ଆୟୋଗର ଅଫିସିଆଲ୍ ୱେବସାଇଟରେ ଲଗଇନ୍ ଆଇଡି ଏବଂ ଜନ୍ମ ତାରିଖ ପ୍ରବେଶ କରନ୍ତୁ | କେବଳ ବ valid ଧ ଆପତ୍ତି ଉପରେ ଚାର୍ଜବ୍ୟାକ୍ ପ୍ରଯୁଜ୍ୟ |",
    "modal_hall_tag": "ଅଫିସିଆଲ୍ ପରୀକ୍ଷା ହଲ୍ ନିୟମାବଳୀ • OMR ସୁବର୍ଣ୍ଣ ନିୟମ",
    "modal_hall_title": "ପରୀକ୍ଷା ଦିବସ ହଲ୍ ମାଷ୍ଟର ଯାଞ୍ଚ ତାଲିକା ଓ OMR ନିୟମ",
    "modal_hall_warning": "<strong> ବାୟୋମେଟ୍ରିକ୍ ଏବଂ ଗେଟ୍ ବନ୍ଦ ଚେତାବନୀ: </ strong> ଆଡମିଟ୍ କାର୍ଡରେ ଉଲ୍ଲେଖ କରାଯାଇଥିବା ଗେଟ୍ ବନ୍ଦ ସମୟର ଅତି କମରେ 45 ମିନିଟ୍ ପୂର୍ବରୁ ପରୀକ୍ଷା କେନ୍ଦ୍ରରେ ପହଞ୍ଚନ୍ତୁ | ଗେଟ୍ ବନ୍ଦ ହେବା ପରେ ମଧ୍ୟ 1 ସେକେଣ୍ଡରେ ବିଳମ୍ବ ହେଲେ ପ୍ରବେଶ ଅନୁମତି ଦିଆଯିବ ନାହିଁ |",
    "modal_sec_mandatory": "✅ ୧. ବାଧ୍ୟତାମୂଳକ ଦସ୍ତାବିଜ୍ (ଏହି ୪ଟି ଜିନିଷ ନିଶ୍ଚୟ ନିଅନ୍ତୁ)",
    "modal_doc1_title": "📄 ୧. ମୂଳ ପ୍ରବେଶ ପତ୍ର (ସ୍ପଷ୍ଟ ପ୍ରିଣ୍ଟଆଉଟ୍)",
    "modal_doc1_desc": "ପ୍ରିଣ୍ଟଆଉଟ୍ ସଫା କର (ରଙ୍ଗ କିମ୍ବା ସଫା କଳା ଏବଂ ଧଳା) | ବାରକୋଡ୍ ଏବଂ ରୋଲ୍ ନମ୍ବରରେ କ wr ଣସି କୁଞ୍ଚନ ରହିବା ଉଚିତ୍ ନୁହେଁ | ପରୀକ୍ଷକଙ୍କ ସାମ୍ନାରେ ସାଇନ୍ ଇନ୍ କରନ୍ତୁ |",
    "modal_doc2_title": "🪪 ୨. ମୂଳ ଫଟୋ ପରିଚୟ ପତ୍ର (ପୂର୍ଣ୍ଣ ଜନ୍ମ ତାରିଖ ସହିତ)",
    "modal_doc2_desc": "ଆଧାର କାର୍ଡ (ଜନ୍ମ ତାରିଖ DD / MM / YYYY ସହିତ) / ପାନ୍ କାର୍ଡ / ଭୋଟର କାର୍ଡ / ଡ୍ରାଇଭିଂ ଲାଇସେନ୍ସ / ପାସପୋର୍ଟ | (ମୋବାଇଲ୍ ଫଟୋ ଅବ alid ଧ) |",
    "modal_doc3_title": "🖼️ ୩. ପାସପୋର୍ଟ ସାଇଜ୍ ଫଟୋ (୨ଟି ଫଟୋ)",
    "modal_doc3_desc": "ଉପସ୍ଥାନ ସିଟ୍ ପାଇଁ ଆଡମିଟ୍ କାର୍ଡରେ ଅପଲୋଡ୍ ହୋଇଥିବା ଫଟୋଗ୍ରାଫ୍ ସହିତ ସର୍ବନିମ୍ନ 2 ପାସପୋର୍ଟ ସାଇଜ୍ ରଙ୍ଗର ଫଟୋଗ୍ରାଫ୍ ବହନ କରନ୍ତୁ |",
    "modal_doc4_title": "🖊️ ୪. ସ୍ୱଚ୍ଛ ବଲ୍‌ପେନ୍ (କଳା / ନୀଳ)",
    "modal_doc4_desc": "ସ୍ୱଚ୍ଛ ଶରୀର କେବଳ କଳା କିମ୍ବା ନୀଳ ବଲ କଲମ | OMR ଉପରେ ଜେଲ୍ ପେନ୍, ount ରଣା କଲମ କିମ୍ବା ପେନ୍ସିଲ୍ କଠୋର ନିଷେଧ |",
    "modal_sec_barred": "🚫 ୨. ସମ୍ପୂର୍ଣ୍ଣ ନିଷିଦ୍ଧ ବସ୍ତୁ (କଠୋର ନିୟମ)",
    "modal_sec_omr": "🎯 ୩. OMR ସିଟ୍ ପୂରଣ କରିବାର ୫ଟି ସୁବର୍ଣ୍ଣ ନିୟମ",
    "modal_omr_r1_title": "ବୃତ୍ତକୁ ସମ୍ପୂର୍ଣ୍ଣ ଗାଢ଼ କରନ୍ତୁ:",
    "modal_omr_r1_desc": "କଲମକୁ କା remove ଼ନ୍ତୁ ନାହିଁ କିମ୍ବା ସର୍କଲ ବାହାରେ ଅସମ୍ପୂର୍ଣ୍ଣ କିମ୍ବା ଟିକ୍ (✓) ରଖନ୍ତୁ ନାହିଁ | ସ୍କାନର୍ କେବଳ ପୂର୍ଣ୍ଣ ଭରାଯାଇଥିବା କଳା / ନୀଳ ସର୍କଲଗୁଡିକ ପ read େ |",
    "modal_omr_r2_title": "ରୋଲ୍ ନମ୍ବର ଏବଂ ପୁସ୍ତିକା କୋଡ୍ ସତର୍କତାର ସହ ପୂରଣ କରନ୍ତୁ:",
    "modal_omr_r2_desc": "ପ୍ରଶ୍ନ ଚେଷ୍ଟା କରିବା ପୂର୍ବରୁ, ରୋଲ୍ ନମ୍ବର, ପ୍ରଶ୍ନ ବୁକଲେଟ୍ ସିରିଜ୍ (A, B, C, D) ଏବଂ ବିଷୟ କୋଡ୍ ଅତି ଯତ୍ନର ସହିତ ପୁରଣ କରନ୍ତୁ |",
    "modal_omr_r3_title": "ଗୋଟିଏ ପ୍ରଶ୍ନ ପାଇଁ କେବଳ ଗୋଟିଏ ବୃତ୍ତ ପୂରଣ କରନ୍ତୁ:",
    "modal_omr_r3_desc": "ଯଦି ଏକ ପ୍ରଶ୍ନର ଦୁଇଟି ସର୍କଲ୍ ପୂର୍ଣ୍ଣ ହୁଏ, ତେବେ ସେହି ଉତ୍ତର ସ୍ୱୟଂଚାଳିତ ଭାବରେ ବାତିଲ ହୋଇଯାଏ ଏବଂ ନକାରାତ୍ମକ ମାର୍କିଂ ସହିତ କାଗଜରେ ମାର୍କ କଟାଯାଇଥାଏ |",
    "modal_omr_r4_title": "OMR ସିଟ୍‌କୁ କେବେ ଭାଙ୍ଗନ୍ତୁ ନାହିଁ କିମ୍ବା ହ୍ୱାଇଟନର୍ ବ୍ୟବହାର କରନ୍ତୁ ନାହିଁ:",
    "modal_omr_r4_desc": "ବ୍ଲେଡ୍ ସ୍କ୍ରାଚ୍ କରିବା, ଇରେଜର କିମ୍ବା ହ୍ it ାଇଟେନର୍ / ଫ୍ଲୁଇଡ୍ ବ୍ୟବହାର କରିବା ସମ୍ପୂର୍ଣ୍ଣ ଭାବେ ନିଷେଧ | ବାରକୋଡ୍ କିମ୍ବା OMR ଶୀଟ୍ ର ଟାଇମିଂ ଟ୍ରାକରେ କ additional ଣସି ଅତିରିକ୍ତ ମାର୍କ କରନ୍ତୁ ନାହିଁ |",
    "modal_omr_r5_title": "ପରିଦର୍ଶକଙ୍କ ଦସ୍ତଖତ ଏବଂ ଆଙ୍ଗୁଠି ଚିହ୍ନ ଯାଞ୍ଚ କରନ୍ତୁ:",
    "modal_omr_r5_desc": "ପରୀକ୍ଷା ସମାପ୍ତ ହେବା ପୂର୍ବରୁ ନିଶ୍ଚିତ କରନ୍ତୁ ଯେ ପରୀକ୍ଷକ ଆପଣଙ୍କର OMR ଦସ୍ତଖତ କରିଛନ୍ତି ଏବଂ ଉପସ୍ଥାନକୁ ଚିହ୍ନିତ କରାଯାଇଛି |",
