    "faq_title": "ବାରମ୍ବାର ପଚରାଯାଉଥିବା ପ୍ରଶ୍ନ (FAQ)",
    "faq_student_desk": "ଛାତ୍ର ସହାୟତା କେନ୍ଦ୍ର (Student Help Desk)",
    "faq_q1": "📸 ଫଟୋ ଓ ଦସ୍ତଖତ ରିସାଇଜର୍ କିପରି କାମ କରେ? ମୋର ଫଟୋ ସୁରକ୍ଷିତ କି?",
    "faq_a1": "ଆପଣଙ୍କର ଫଟୋ ଏବଂ ଦସ୍ତଖତ 100% ସୁରକ୍ଷିତ ଅଟେ | ଏହି ଟୁଲ୍ ବ୍ରାଉଜର୍ ଭିତରେ ଚାଲିଥାଏ (ଏକ କ୍ଲାଏଣ୍ଟ-ସାଇଡ୍ HTML5 କାନଭାସରେ) ଏବଂ କ any ଣସି ସର୍ଭରରେ ଅପଲୋଡ୍ କିମ୍ବା ଗଚ୍ଛିତ ନୁହେଁ | ଏହା ତୁରନ୍ତ ସରକାରୀ 20-50 KB ଏବଂ SSC, UPSC, ରେଳବାଇ ଏବଂ ରାଜ୍ୟ ପୋଲିସର ପିକ୍ସେଲ ଆବଶ୍ୟକତା ପୂରଣ କରେ |",
    "faq_q2": "📑 ଅଫିସିଆଲ୍ ବିଜ୍ଞପ୍ତି ସର୍କୁଲାର୍ ଡିକୋଡର୍ କ’ଣ?",
    "faq_a2": "ସରକାରୀ ନିଯୁକ୍ତି ବିଜ୍ଞପ୍ତିର 50-60 ପୃଷ୍ଠାରୁ, ଆବେଦନପତ୍ରର ଶେଷ ତାରିଖ, ମୋଟ ପୋଷ୍ଟ, ପେ ସ୍କେଲ, ବୟସ ସୀମା, ପରୀକ୍ଷା pattern ାଞ୍ଚା ଏବଂ ଆବଶ୍ୟକୀୟ ଦଲିଲଗୁଡ଼ିକ ଗୁରୁତ୍ୱପୂର୍ଣ୍ଣ ଭାଷାରେ 1 ମିନିଟରେ ଉପସ୍ଥାପିତ ହୋଇଛି |",
    "faq_q3": "📚 ₹୧୦ ଅଧ୍ୟୟନ ନୋଟ୍ସ ଏବଂ ପୂର୍ବ ବର୍ଷ ପ୍ରଶ୍ନ (PYQ) କିପରି ପାଇବେ?",
    "faq_a3": "ପରୀକ୍ଷା ଚୟନ କରି ତୁମର ପ୍ରିୟ ବିଷୟର ନୋଟ୍ ବାଛ | ଫୋନ୍ପି, ଗୁଗୁଲ୍ ପେ କିମ୍ବା ପେଟିଏମ୍ ମାଧ୍ୟମରେ ସିଧାସଳଖ UPI QR ଦେୟ ପ୍ରଦାନ କରିବା ତୁରନ୍ତ ଉଚ୍ଚ-ଗୁଣାତ୍ମକ PDF ଡାଉନଲୋଡ୍ ଅନଲକ୍ କରେ |",
    "faq_q4": "🎂 ବୟସ ଗଣନାରେ (Age Calculator) ସଂରକ୍ଷଣ ରିହାତି କିପରି ଗଣାଯାଏ?",
    "faq_a4": "ପ୍ରକୃତ ହିସାବ କମିଶନ କଟଅଫ ତାରିଖ ଏବଂ ଜନ୍ମ ତାରିଖ ଆଧାରରେ କରାଯାଇଥାଏ | ଏଥିରେ, OBC ପାଇଁ 3 ବର୍ଷ, SC / ST ପାଇଁ 5 ବର୍ଷ, PwBD ପାଇଁ 10-15 ବର୍ଷ ଏବଂ ପୂର୍ବତନ ସେବାୟତଙ୍କ ପାଇଁ ନିୟମ ଅନୁଯାୟୀ ଆରାମ ସ୍ୱୟଂଚାଳିତ ଭାବରେ ପ୍ରୟୋଗ କରାଯାଏ |",
    "faq_q5": "🌐 ପୋର୍ଟାଲରେ ଥିବା ସମସ୍ତ ଲିଙ୍କ୍ ୧୦୦% ଅଫିସିଆଲ୍ କି?",
    "faq_a5": "ହଁ! ଆମର ସିଷ୍ଟମ୍ 24x7 ସ୍ୱୟଂଚାଳିତ ଭାବରେ ସରକାରୀ ଆୟୋଗର ସର୍ଭରଗୁଡ଼ିକୁ ଯାଞ୍ଚ କରେ (.gov.in, .nic.in, .ac.in) | ନକଲି କିମ୍ବା ବିଭ୍ରାନ୍ତିକର ବିଜ୍ଞାପନ ଧାରଣ କରିଥିବା କ website ଣସି ୱେବସାଇଟ୍ ସହିତ ଲିଙ୍କ୍ ପ୍ରଦାନ କରାଯାଇ ନାହିଁ |",
