    "faq_student_desk": "छात्र-सहायता-केन्द्रम् (Student Help Desk)",
    "faq_q1": "📸 चित्र-हस्ताक्षर-परिमाणकः कथं कार्यं करोति? किं मम चित्रं सुरक्षितम्?",
    "faq_a1": "भवतः चित्रं हस्ताक्षरं च १००% सुरक्षितम् अस्ति। एतत् साधनं केवलं जालपुट-अन्तर्गतम् (Client-side HTML5 Canvas) कार्यं करोति, कोऽपि सञ्चिका सर्वरे न आरोप्यते। SSC, UPSC, रेल-आरक्षक-प्रवेशपत्रार्थं २०-५० KB परिमाणं जनयति।",
    "faq_q2": "📑 आधिकारिक-अधिसूचना-विवरणकः कः?",
    "faq_a2": "५०-६० पृष्ठात्मकात् अधिसूचना-पत्रात् आवेदन-अन्तिमतिथिम्, रिक्तपदानि, वेतनानि, वयः-सीमाम् च १ निमेषे सरलतया बोधयति।",
    "faq_q3": "📚 ₹१० अध्ययन-टिप्पणी-प्रश्नपत्राणि कथं प्राप्यन्ते?",
    "faq_a3": "परीक्षाम् चित्वा PhonePe, Google Pay अथवा Paytm माध्यमेन केवलं ₹१० UPI-शुल्कं प्रदाय तत्क्षणमेव उच्चगुणवत्तायुतं PDF प्राप्नुवन्तु।",
    "faq_q4": "🎂 वयः-गणनायां आरक्षण-छूट कथं गण्यते?",
    "faq_a4": "आयोगस्य अन्तिम-तिथ्या जन्मतारिकया च आधारेण OBC कृते ३ वर्षाणि, SC/ST कृते ५ वर्षाणि, PwBD कृते १०-१५ वर्षाणि च वयः-छूट स्वयमेव योज्यते।",
    "faq_q5": "🌐 किं जालपुटे दत्ताः सर्वे सम्पर्क-तन्तवः १००% आधिकारिकाः सन्ति?",
    "faq_a5": "आम्! सर्वे सम्पर्क-तन्तवः २४x७ सर्वकारीय-जालपुटैः सह प्रमाणीकृताः सन्ति।",
