    "modal_hall_warning": "<strong>বায়’মেট্ৰিক আৰু গেট বন্ধ কৰাৰ সতৰ্কবাণী:</strong> এডমিট কাৰ্ডত উল্লেখ কৰা গেট বন্ধ কৰাৰ সময়ৰ কমেও ৪৫ মিনিট আগতে পৰীক্ষা কেন্দ্ৰত উপস্থিত হওক। গেট বন্ধ হোৱাৰ পিছতো ১ ছেকেণ্ড পলম হ’লে প্ৰৱেশৰ অনুমতি দিয়া নহ’ব।",
    "modal_sec_mandatory": "✅ ১. বাধ্যতামূলক নথিপত্ৰ (এই ৪টা বস্তু নিশ্চিতভাৱে আনক)",
    "modal_doc1_title": "📄 ১. মূল এডমিট কাৰ্ড (পৰিষ্কাৰ প্ৰিণ্টআউট)",
    "modal_doc1_desc": "প্ৰিন্টআউটসমূহ পৰিষ্কাৰ কৰক (ৰঙ বা পৰিষ্কাৰ ক'লা আৰু বগা)। বাৰক’ড আৰু ৰোল নম্বৰত কোনো ধৰণৰ বলিৰেখা থাকিব নালাগে। পৰীক্ষকৰ সন্মুখত চহী কৰক।",
    "modal_doc2_title": "🪪 ২. মূল ফটো পৰিচয় পত্ৰ (সম্পূৰ্ণ জন্ম তাৰিখ সহ)",
    "modal_doc2_desc": "আধাৰ কাৰ্ড (সম্পূৰ্ণ জন্ম তাৰিখ DD/MM/YYYY সহ) / পেন কাৰ্ড / ভোটাৰ কাৰ্ড / ড্ৰাইভিং লাইচেন্স / পাছপ'ৰ্ট। (মোবাইল ফটো অবৈধ)।",
    "modal_doc3_title": "🖼️ ৩.পাছপ'ৰ্টৰ আকাৰৰ ফটোগ্ৰাফ (২ ফটো)",
    "modal_doc3_desc": "উপস্থিতি শ্বীটৰ বাবে এডমিট কাৰ্ডত আপলোড কৰা ফটোৰ সৈতে একেধৰণৰ নূন্যতম ২খন পাছপ’ৰ্ট আকাৰৰ ৰঙীন ফটো লৈ যাব লাগে।",
    "modal_doc4_title": "🖊️ ৪. স্বচ্ছ বলপইণ্ট কলম (ক'লা / নীলা)",
    "modal_doc4_desc": "স্বচ্ছ শৰীৰ ক’লা বা নীলা বল পেন কেৱল। OMR ত জেল পেন, ফাউণ্টেইন পেন বা পেঞ্চিল কঠোৰভাৱে নিষিদ্ধ।",
    "modal_sec_barred": "🚫 ২. সম্পূৰ্ণ নিষিদ্ধ সামগ্ৰী (Zero Tolerance)",
    "modal_sec_omr": "🎯 ৩. OMR শ্বীট পূৰণৰ ৫টা সোণালী নিয়ম",
    "modal_omr_r1_title": "বৃত্তটো সম্পূৰ্ণৰূপে ডাঠকৈ ভৰাওক (● শুদ্ধ vs ✕ ভুল):",
    "modal_omr_r1_desc": "কলমটো আঁতৰাই নিদিব বা বৃত্তৰ বাহিৰত অসম্পূৰ্ণ বা টিক (✓) নিদিব। স্ক্যানাৰে কেৱল সম্পূৰ্ণ ভৰ্তি ক’লা/নীলা বৃত্তহে পঢ়ে।",
    "modal_omr_r2_title": "ৰোল নম্বৰ আৰু বুকলেট ক'ড প্ৰথমে সাৱধানে পূৰণ কৰক:",
    "modal_omr_r2_desc": "প্ৰশ্নটোৰ চেষ্টা কৰাৰ আগতে ৰোল নম্বৰ, প্ৰশ্ন পুস্তিকা ছিৰিজ (ক, খ, গ, ঘ) আৰু বিষয় ক’ড অতি সাৱধানে পূৰণ কৰক।",
    "modal_omr_r3_title": "এটা প্ৰশ্নত কেৱল এটা বৃত্তহে ভৰাব (No Double Bubbling):",
    "modal_omr_r3_desc": "যদি কোনো এটা প্ৰশ্নৰ দুটা বৃত্ত পূৰণ কৰা হয়, তেন্তে সেই উত্তৰটো স্বয়ংক্ৰিয়ভাৱে বাতিল কৰা হয় আৰু কাগজখনত ঋণাত্মক চিহ্নৰে নম্বৰ কৰ্তন কৰা হয়।",
    "modal_omr_r4_title": "OMR কেতিয়াও ভাঁজ নকৰিব আৰু হোৱাইটনাৰ/ইৰেজাৰ ব্যৱহাৰ সম্পূৰ্ণ নিষিদ্ধ:",
    "modal_omr_r4_desc": "ব্লেডখন আঁচোৰোৱা, ইৰেজাৰ বা হোৱাইটনাৰ/ফ্লুইড ব্যৱহাৰ কৰাটো কঠোৰভাৱে নিষিদ্ধ। অ’এমআৰ শ্বীটৰ বাৰক’ড বা টাইমিং ট্ৰেকত কোনো অতিৰিক্ত চিহ্ন নিদিব।",
    "modal_omr_r5_title": "পৰিদৰ্শকৰ স্বাক্ষৰ আৰু উপস্থিতি পত্ৰত বুঢ়া আঙুলিৰ চাপ পৰীক্ষা:",
    "modal_omr_r5_desc": "পৰীক্ষা শেষ হোৱাৰ আগতে নিশ্চিত কৰক যে পৰীক্ষকে আপোনাৰ অ’এমআৰত চহী কৰিছে আৰু উপস্থিতি চিহ্নিত কৰা হৈছে।",
