    "qual_iti": "ITI / ডিপ্ল'মা",
    "faq_title": "সঘনাই সোধা প্ৰশ্ন (FAQ)",
    "faq_student_desk": "ছাত্ৰ-ছাত্ৰী সাহায্য কেন্দ্ৰ (Help Desk)",
    "faq_q1": "📸 ফটো আৰু স্বাক্ষৰ ৰিজাইজাৰ কেনেকৈ ব্যৱহাৰ কৰিব? মোৰ ফটো সুৰক্ষিত নে?",
    "faq_a1": "আপোনাৰ ফটো আৰু স্বাক্ষৰ ১০০% সুৰক্ষিত। এই সঁজুলি ব্ৰাউজাৰৰ ভিতৰত (এটা ক্লাএন্ট-পক্ষৰ HTML5 কেনভাছত) চলি থাকে আৰু কোনো চাৰ্ভাৰত আপলোড বা সংৰক্ষণ কৰা নহয়। ই তৎক্ষণাত এছ এছ চি, ইউ পি এছ চি, ৰেলৱে আৰু ৰাজ্যিক আৰক্ষীৰ চৰকাৰী ২০-৫০ কে বি আৰু পিক্সেলৰ প্ৰয়োজনীয়তা পূৰণ কৰে।",
    "faq_q2": "📑 অফিচিয়েল জাননী ডিক'ডাৰ কি?",
    "faq_a2": "চৰকাৰী নিযুক্তিৰ অধিসূচনাৰ ৫০-৬০ পৃষ্ঠাৰ ভিতৰত আবেদনৰ শেষ তাৰিখ, মুঠ পদ, দৰমহাৰ স্কেল, বয়সৰ সীমা, পৰীক্ষাৰ ধৰণ আৰু প্ৰয়োজনীয় নথি-পত্ৰ আদি গুৰুত্বপূৰ্ণ কথা ১ মিনিটত সহজ ভাষাত উপস্থাপন কৰা হয়।",
    "faq_q3": "📚 ₹১০ নোট আৰু প্ৰশ্নোত্তৰ কেনেকৈ সংগ্ৰহ কৰিব?",
    "faq_a3": "পৰীক্ষা নিৰ্বাচন কৰি আপোনাৰ প্ৰিয় বিষয়ৰ টোকা বাছি লওক। PhonePe, Google Pay বা Paytm ৰ জৰিয়তে মাত্ৰ ₹10 টকাৰ প্ৰত্যক্ষ UPI QR পেমেণ্ট কৰিলে তৎক্ষণাত উচ্চমানৰ PDF ডাউনলোড আনলক হয়।",
    "faq_q4": "🎂 বয়স গণকত সংৰক্ষণৰ ৰেহাই কেনেকৈ গণনা কৰা হয়?",
    "faq_a4": "কমিচন কাটঅফ তাৰিখ আৰু জন্ম তাৰিখৰ ভিত্তিত সঠিক হিচাপ কৰা হয়। ইয়াত অ’বিচিৰ বাবে ৩ বছৰ, এছচি/এছটিৰ বাবে ৫ বছৰ, পিডব্লিউবিডিৰ বাবে ১০-১৫ বছৰ আৰু প্ৰাক্তন সেনাবাহিনীৰ বাবে নিয়ম অনুসৰি শিথিলতা স্বয়ংক্ৰিয়ভাৱে প্ৰয়োগ কৰা হয়।",
    "faq_q5": "🌐 পৰ্টেলৰ সকলো লিংক ১০০% চৰকাৰী আৰু নিৰাপদ নে?",
    "faq_a5": "হয়! আমাৰ চিষ্টেমে ২৪x৭ স্বায়ত্তশাসিতভাৱে অফিচিয়েল কমিচনৰ চাৰ্ভাৰসমূহ পৰীক্ষা কৰে (.gov.in, .nic.in, .ac.in)। ভুৱা বা বিভ্ৰান্তিকৰ বিজ্ঞাপন থকা যিকোনো ৱেবছাইটৰ লিংক দিয়া নহয়।",
