    "faq_student_desk": "विद्यार्थी सहायता केंद्र",
    "faq_q1": "📸 फोटो आ दस्तखत रिसाइजर कइसे काम करेला? का हमार फोटो सेफ बा?",
    "faq_a1": "राउर फोटो आ दस्तखत 100% सुरक्षित बा। ई टूल ब्राउजर के अंदर चलेला, कवनो सर्वर पर अपलोड ना होला।",
