    "faq_a2": "सरकारी भर्ती के 50-60 पन्ना में से जरूरी बात जइसे आखिरी तारीख, कुल पद, उमिर सीमा 1 मिनट में आसान भाषा में बतावेला।",
    "faq_q3": "📚 ₹10 नोट्स आ PYQ कइसे पाईं?",
    "faq_a3": "परीक्षा आ विषय चुनीं। PhonePe, Google Pay भा Paytm से ₹10 के सीधा UPI भुगतान क के तुरंत PDF डाउनलोड करीं।",
