    "faq_q1": "📸 فوٽو ۽ صحيح ريسائيزر ڪيئن ڪم ڪري ٿو؟ ڇا منهنجو فوٽو محفوظ آهي؟",
    "faq_a1": "توهان جو فوٽو ۽ صحيح 100٪ محفوظ آهي. هي اوزار مڪمل طور تي برائوزر ۾ هلندو آهي، ڪا به فائل سرور تي اپ لوڊ نه ٿيندي آهي.",
