    "faq_a2": "سرڪاري ڀرتي جي 50-60 صفحن مان اهم ڳالهيون جيئن آخري تاريخ، ڪل جايون، عمر جي حد ۽ فارم جا اصول 1 منٽ ۾ سادي ٻوليءَ ۾ پيش ڪري ٿو.",
