    "faq_title": "اکثر پوچھے جانے والے سوالات (FAQ)",
    "faq_student_desk": "طلباء ہیلپ ڈیسک (Student Help Desk)",
    "faq_q1": "📸 فوٹو تہٕ دستخط ہُنٛد سائز بدلنے والا ٹول ہٕنٛزنِش ہُنٛدم کرتا چھُ؟ ہٕنٛزا میری تصویر محفوظ چھُ؟",
    "faq_a1": "آپ ہٕنٛز تصویر تہٕ دستخط 100% محفوظ چھِ۔ یہ ٹول مکمل طور پؠٹھ آپ ہٕنٛدی براؤزر ہٕنٛدی اندر (Client-side HTML5 Canvas) چلتا چھُ، کسی سرور پؠٹھ اپ لوڈ نچھِ ہوتا۔ SSC، UPSC، ریلوے تہٕ پولیس فارم خٲطرٕ 20-50 KB منٛز سائز بناتا چھُ۔",
    "faq_q2": "📑 آفیشل نوٹیفہٕنٛزشن سرکلر ڈیکوڈر ہٕنٛزا چھُ؟",
    "faq_a2": "50-60 صفحات ہٕنٛدی طویل نوٹیفہٕنٛزشن منٛز نِش آخری تاریخ، اسامیاں، تنخواہ، عمر ہٕنٛز حد تہٕ نصاب 1 منٹ منٛز آسان اردو منٛز پیش کرتا چھُ۔",
    "faq_q3": "📚 ₹10 اسٹڈی نوٹس تہٕ پؠٹھانے سوالیہ پؠٹھچے ہٕنٛزنِش حاصل کٔرِو؟",
    "faq_a3": "اِمتحان منتخب کٔرِو تہٕ PhonePe، Google Pay یا Paytm نِش صرف ₹10 ہٕنٛز فوری UPI ادائیگی کر ہٕنٛدی فوراً اعلیٰ معیار ہٕنٛز PDF ڈاؤن لوڈ کٔرِو۔",
    "faq_q4": "🎂 ایج ہٕنٛزلکولیٹر منٛز ریزرویشن ہٕنٛز رعایت ہٕنٛزنِش شمار ہٕنٛز جاتی چھُ؟",
    "faq_a4": "آفیشل کٹ آف تاریخ تہٕ تاریخ پیدائش ہٕنٛدی مطابق OBC کو 3 سال، SC/ST کو 5 سال، تہٕ معذور افراد کو 10-15 سال ہٕنٛز چھوٹ خود بخود مل جاتی چھُ۔",
    "faq_q5": "🌐 ہٕنٛزا پورٹل پؠٹھ دیے گئے تمام لنکس 100% آفیشل چھِ؟",
    "faq_a5": "جی ہاں! تمام لنکس 24x7 سرہُنٛدری پورٹلز (.gov.in, .nic.in) نِش تصدیق شدہ چھِ۔",
