    "faq_title": "ᱡᱟᱣ ᱜᱮ ᱠᱩᱞᱤᱭᱟᱱ ᱠᱩᱠᱞᱤ (FAQ)",
    "faq_student_desk": "ᱯᱟᱹᱴᱷᱩᱣᱟᱹ ᱜᱚᱲᱚ ᱛᱟᱞᱢᱟ (Help Desk)",
    "faq_q1": "📸 ᱪᱤᱛᱟᱹᱨ ᱟᱨ ᱥᱩᱦᱤ ᱨᱤᱥᱟᱭᱤᱡᱟᱨ ᱪᱮᱫ ᱞᱮᱠᱟ ᱠᱟᱹᱢᱤᱭᱟ? ᱪᱮᱫ ᱪᱤᱛᱟᱹᱨ ᱨᱩᱠᱷᱤᱭᱟᱹ ᱜᱮᱭᱟ?",
    "faq_a1": "ᱟᱢᱟᱜ ᱪᱤᱛᱟᱹᱨ ᱟᱨ ᱥᱩᱦᱤ 100% ᱨᱩᱠᱷᱤᱭᱟᱹ ᱜᱮᱭᱟ᱾ ᱱᱚᱶᱟ ᱴᱩᱞ ᱵᱨᱟᱣᱩᱡᱟᱨ ᱨᱮᱜᱮ ᱠᱟᱹᱢᱤᱭᱟ, ᱥᱟᱨᱵᱷᱟᱨ ᱨᱮ ᱵᱟᱝ ᱨᱟᱠᱟᱵᱚᱜᱼᱟ᱾",
    "faq_q2": "📑 ᱚᱯᱷᱤᱥᱤᱭᱟᱞ ᱠᱷᱚᱵᱚᱨ ᱰᱤᱠᱳᱰᱟᱨ ᱪᱮᱫ ᱠᱟᱱᱟ?",
    "faq_a2": "ᱥᱚᱨᱠᱟᱨᱤ ᱪᱟᱹᱠᱨᱤ ᱨᱮᱱᱟᱜ ᱕᱐-᱖᱐ ᱥᱟᱠᱟᱢ ᱠᱷᱚᱱ ᱡᱟᱹᱨᱩᱲᱤ ᱠᱟᱛᱷᱟ ᱡᱮᱞᱮᱠᱟ ᱢᱩᱪᱟᱹᱫ ᱢᱟᱹᱦᱤᱛ, ᱯᱚᱫᱽ, ᱩᱢᱮᱨ ᱑ ᱴᱤᱯᱤᱡ ᱨᱮ ᱵᱩᱡᱷᱟᱹᱣ ᱮᱢᱚᱜᱼᱟ᱾",
    "faq_q3": "📚 ₹10 ᱱᱳᱴᱥ ᱟᱨ PYQ ᱪᱮᱫ ᱞᱮᱠᱟ ᱧᱟᱢᱚᱜᱼᱟ?",
    "faq_a3": "ᱵᱤᱱᱤᱰ ᱟᱨ ᱥᱟᱛᱟᱢ ᱵᱟᱪᱷᱟᱣ ᱢᱮ᱾ PhonePe, Google Pay ᱥᱮ Paytm ᱛᱮ ₹10 UPI ᱮᱢ ᱠᱟᱛᱮ ᱞᱚᱜᱚᱱ PDF ᱰᱟᱣᱩᱱᱞᱳᱰ ᱢᱮ᱾",
    "faq_q4": "🎂 ᱩᱢᱮᱨ ᱦᱤᱥᱟᱹᱵᱽ ᱨᱮ ᱪᱷᱟᱰ ᱪᱮᱫ ᱞᱮᱠᱟ ᱞᱮᱠᱷᱟᱜᱼᱟ?",
    "faq_a4": "ᱠᱟᱴᱚᱯᱷ ᱢᱟᱹᱦᱤᱛ ᱟᱨ ᱡᱟᱱᱟᱢ ᱢᱟᱹᱦᱤᱛ ᱞᱮᱠᱟᱛᱮ ᱦᱤᱥᱟᱹᱵᱽ ᱦᱩᱭᱩᱜᱼᱟ᱾ OBC (᱓ ᱥᱮᱨᱢᱟ), SC/ST (᱕ ᱥᱮᱨᱢᱟ) ᱪᱷᱟᱰ ᱟᱯᱱᱟᱨ ᱛᱮ ᱞᱟᱜᱟᱣᱜᱼᱟ᱾",
    "faq_q5": "🌐 ᱪᱮᱫ ᱯᱳᱨᱴᱟᱞ ᱨᱮᱭᱟᱜ ᱥᱟᱱᱟᱢ ᱞᱤᱝᱠ 100% ᱥᱚᱨᱠᱟᱨᱤ ᱟᱨ ᱨᱩᱠᱷᱤᱭᱟᱹ ᱜᱮᱭᱟ?",
