    "faq_student_desk": "फरायसुला सहायता निंद्र (Student Help Desk)",
    "faq_q1": "📸 फोटो व हस्ताक्षर रिसाइज़र कैसे निम करता दं? क्या मेरा फोटो सुरक्षित दं?",
    "faq_a1": "आपनि फोटो आरो सिग्नेचर 100% सुरक्षित दं। यह टूल ब्राउज़र नि अंदर (Client-side HTML5 Canvas पर) चलता दं, किसी सर्वर पर अपलोड या स्टोर नहीं होता। यह SSC, UPSC, रेलवे आरो राज्य पुलिस नि आधिनिरिक 20-50 KB आरो पिक्सेल आवश्यकताओं को तुरंत पूरा करता दं।",
    "faq_q2": "📑 आधिनिरिक नोटिफिनिशन सर्कुलर डिकोडर क्या दं?",
    "faq_a2": "सरनिरी भर्ती नि 50-60 पन्नों नि नोटिफिनिशन में से जरूरी बातें जैसे आवेदन नि अंतिम तिथि, कुल पद, वेतनमान, आयु सीमा, आनजाद पैटर्न आरो आवश्यक दस्तावेज 1 मिनट में आसान भाषा में प्रस्तुत किए जाते दंं।",
    "faq_q3": "📚 ₹10 स्टडी नोट्स आरो PYQ कैसे प्राप्त खालाम?",
    "faq_a3": "आनजाद चयन करनि अपने पसंदीदा विषय नि नोट्स चुनें। PhonePe, Google Pay या Paytm से मात्र ₹10 नि सीधा UPI QR भुगतान करने पर तुरंत उच्च-गुणवत्ता PDF डाऊनलोड अनलॉक हो जाता दं।",
    "faq_q4": "🎂 आयु गणना (Age Calculator) में आरक्षण छूट कैसे गिनी जाती दं?",
    "faq_a4": "आयोग नि कटऑफ तिथि आरो जन्मतिथि नि आधार पर सटीक गणना नि जाती दं। इसमें OBC को 3 वर्ष, SC/ST को 5 वर्ष, PwBD को 10-15 वर्ष आरो भूतपूर्व सैनिकों को नियमानुसार छूट स्वतः लागू नि जाती दं।",
    "faq_q5": "🌐 क्या पोर्टल पर दी गई सभी लिंक्स 100% आधिनिरिक (Official) दंं?",
    "faq_a5": "हाँ! हमारा सिस्टम 24x7 स्वायत्त रूप से आधिनिरिक आयोगों (.gov.in, .nic.in, .ac.in) नि सर्वरों को सत्यापित करता दं। किसी भी फर्जी या भ्रामक विज्ञापन वाली वेबसाइट नि लिंक नहीं दिया जाता।",
